export const getResponse = (content) => {
    const res = getResponse_backend(content);
    let JSON = parse(res);
    let response = JSON.response;
    let score = parseInt(JSON.score);

    let json_arr = [];
    json_arr.push({
        answer: response,
        score: score
    });
    return json_arr
}



